CURLcode base64_plain_auth(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t plain_len = user_len + 1 + pass_len;
  size *b64_len;

  /* Calculate the length of the Base64 encoded string */
  size_t b64_len = ((plain_len + 2) / 3) * 4;

  /* Allocate memory for the output string */
  char *result = malloc(b64_len + 1);
  if (!result) {
    return CURLE_OUT_OF_MEMORY;
  }

  /* Build the PLAIN message: \0username\0password */
  char *plain = malloc(plain_len + 1);
  if (!plain) {
    free(result);
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[user_len + 1 + pass_len] = '\0';

  /* Encode the PLAIN message in Base64 */
  CURLcode res = Curl_base64encode(data, plain, plain_len, &result, &b64_len);

  free(plain);

  if (res != CURLE_OK) {
    free(result);
    return res;
  }

  *outptr = result;
  *outlen = b64_len;

  return CURLE_OK;
}

CURLcode base64_plain_auth(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t plain_len = user_len + 1 + pass_len;
  size_t base64_len = Curl_base64_encode_len(plain_len);
  char *plain = NULL;
  char *base64 = NULL;
  CURLcode result = CURLE_OUT_OF_MEMORY;

  if (base64_len == 0) {
    return CURLE_OUT_OF_MEMORY;
  }

  plain = malloc(plain_len);
  if (!plain) {
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);

  base64 = malloc(base64_len);
  if (!base64) {
    free(plain);
    return CURLE_OUT_OF_MEMORY;
  }

  result = Curl_base64_encode(data, plain, plain_len, &base64, outlen);
  if (result == CURLE_OK) {
    *outptr = base64;
  } else {
    free(plain);
    free(base64);
  }

  return result;
}

CURLcode Curl_auth_negotiate_plain(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t plain_len = user_len + pass_len + 2; // user\x00pass\x00
  size_t base64_len = Curl_base64_size(data, plain_len);

  if(base64_len > SIZE_MAX - 1)
    return CURLE_OUT_OF_MEMORY;

  char *plain = malloc(plain_len);
  if(!plain)
    return CURLE_OUT_OF_MEMORY;

  // Construct the PLAIN message
  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[user_len + 1 + pass_len] = '\0';

  // Base64 encode the PLAIN message
  char *base64 = Curl_base64encode(data, plain, plain_len);
  free(plain);

  if(!base64) {
    return CURLE_OUT_OF_MEMORY;
  }

  *outptr = base64;
  *outlen = strlen(base64);

  return CURLE_OK;
}

CURLcode generate_plain_auth_message(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t total_len = user_len + 1 + pass_len + 1; /* user\0pass\0 */
  size_t base64_len = Curl_base64_encode(data, NULL, 0, total_len, NULL);

  if (!base64_len || base64_len == (size_t)-1) {
    return CURLE_OUT_OF_MEMORY;
  }

  char *encoded = (char *)Curl_safefree(*outptr);
  if (!encoded) {
    return CURLE_OUT_OF_MEMORY;
  }

  char *plain = (char *)malloc(total_len);
  if (!plain) {
    free(encoded);
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[user_len + 1 + pass_len] = '\0';

  CURLcode result = Curl_base64_encode(data, plain, total_len, encoded, &base64_len);
  if (result != CURLE_OK) {
    free(encoded);
    free(plain);
    return result;
  }

  *outptr = encoded;
  *outlen = base64_len;

  free(plain);
  return CURLE_OK;
}
